#!/usr/bin/env python3
import json, os, html, re
ROOT=os.path.dirname(os.path.abspath(__file__))
R=json.load(open(os.path.join(ROOT,"data","rows.json")))
DOCS=os.path.join(ROOT,"docs")
def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def e(x): return html.escape(str(x if x!="" else "—"))
SPORTS=[]
for r in R:
    if r["sport"] not in SPORTS: SPORTS.append(r["sport"])
CSS="""body{font-family:system-ui,Arial,sans-serif;margin:0;background:#0f172a;color:#e2e8f0}header{background:#020617;padding:18px 24px}header a{color:#38bdf8;text-decoration:none;margin-right:14px}main{max-width:1180px;margin:auto;padding:20px}table{border-collapse:collapse;width:100%;font-size:13px;background:#111827}th,td{border:1px solid #334155;padding:6px;vertical-align:top}th{background:#1e293b}.card{background:#1e293b;border-radius:10px;padding:14px;margin:8px 0}.card a{color:#7dd3fc}.flag{color:#fbbf24}.High{color:#4ade80;font-weight:700}.Medium{color:#facc15}.Low{color:#94a3b8}small{color:#94a3b8}"""
open(os.path.join(DOCS,"assets.css"),"w").write(CSS)
def nav(prefix=""):
    links=f'<a href="{prefix}index.html">Home</a><a href="{prefix}methodology.html">Methodology &amp; Markets</a><a href="{prefix}flagged.html">Flagged for Review</a>' + "".join(f'<a href="{prefix}sports/{slug(s)}.html">{e(s)}</a>' for s in SPORTS)
    return f"<header><strong>OLBG4 — Originated Lines Dashboard</strong><br>{links}<p><small>Snapshot 21 Oct 2026 · Window 21–25 Oct 2026 · Our own lines (Model v1), not bookmaker odds · Every row links to an official source · Blank = unverified, never guessed · 18+ Gamble responsibly — this is analysis, not betting advice.</small></p></header>"
def table(rows):
    th="<tr><th>Date</th><th>Competition</th><th>Match</th><th>Markets investigated</th><th>Our line (home / away)</th><th>Pick</th><th>Confidence</th><th>Verified basis (form &amp; history used)</th><th>Official source</th><th>Status</th></tr>"
    out=[]
    for r in rows:
        match=f"{e(r['home'])}{' v ' if r['away'] else ''}{e(r['away'])}<br><small>{e(r['time'])} {e(r['venue'])}</small>"
        if r["prediction"]: match+=f"<p><strong>Prediction:</strong> {e(r['prediction'])}</p>"
        line=f"{e(r['our_line_home'])} / {e(r['our_line_away'])}<br><small>model P(home)={e(r['model_prob_home'])}</small>" if r["our_line_home"]!="" else "— (not originated)"
        out.append(f"<tr><td>{e(r['date'])}</td><td>{e(r['competition'])}</td><td>{match}</td><td>{e(r['markets_investigated'])}</td><td>{line}</td><td>{e(r['pick'])}</td><td class='{e(r['confidence'])}'>{e(r['confidence'])}</td><td>{e(r['basis'])}</td><td><a href='{e(r['source'])}'>{e(r['source_label'])}</a></td><td>{e(r['status'])}</td></tr>")
    return "<table>"+th+"".join(out)+"</table>"
for s in SPORTS:
    rows=[r for r in R if r["sport"]==s]
    open(os.path.join(DOCS,"sports",slug(s)+".html"),"w").write(f"<!doctype html><html><head><meta charset='utf-8'><title>{e(s)} — OLBG4</title><link rel='stylesheet' href='../assets.css'></head><body>{nav('../')}<main><h1>{e(s)}</h1><p>{len(rows)} row(s) in the 21–25 Oct 2026 window. Lines are originated by Model v1 (see Methodology); they are not copied from OLBG or any bookmaker.</p>{table(rows)}</main></body></html>")
flagged=[r for r in R if r["status"]=="Flagged"]
extra="""<div class='card'><h2>Cross-source irregularities found during verification</h2><ol>
<li><strong>Snooker pairing mismatch:</strong> OLBG listed “Cheung Ka Wai v Stuart Bingham” for 21 Oct, but WST's official match centre lists Cheung Ka Wai in Round 2 v the winner of Match 20 after beating Ronnie O'Sullivan, with Stuart Bingham playing Yao Pengcheng in Round 1. The OLBG pairing is not confirmed by the official source, so our opponent field is blank. Source: <a href='https://www.wst.tv/northernirelandopen/'>WST Northern Ireland Open</a>.</li>
<li><strong>Galway final time mismatch:</strong> OLBG listed Moycullen v Salthill-Knocknacarra at 14:00 on 24 Oct; Galway GAA's official fixtures list the Co. Final at 19:00 at Pearse Stadium. We use the official time. Source: <a href='https://www.galwaygaa.ie/fixtures/?user=6929'>Galway GAA fixtures</a>.</li>
<li><strong>Cork final time mismatch:</strong> OLBG listed St Finbarr's v Nemo Rangers at 12:00 on 25 Oct; Cork GAA lists the Premier SFC Final at 16:00 at SuperValu Páirc Uí Chaoimh. We use the official time. Source: <a href='https://gaacork.ie/event/mccarthy-insurance-group-premier-senior-football-championship-final/'>Cork GAA</a>.</li>
<li><strong>Model conflict — Australia v Fiji (Rugby League):</strong> the Round 1 winning-margin rating favours Fiji, while the NRL's verified world-ranking statement favours Australia (top-two ranked). Pick follows the ranking input at Low confidence; see the Rugby League page.</li>
<li><strong>Scope limit (honesty note):</strong> OLBG lists 20+ sports and many more leagues and county/club competitions than can be verified line-by-line from official sources in one snapshot. This site covers, for 21–25 Oct 2026, every included sport and the competitions within it whose pairings could be confirmed on an official governing-body/league site. Competitions whose pairings could not be so confirmed appear as flagged tournament rows rather than invented matches. “Full list” therefore means the full verified list for this window under that rule — not every grassroots fixture worldwide.</li>
<li><strong>Handicap &amp; totals:</strong> for basketball, ice hockey, rugby, handball, baseball and Gaelic football, handicap and match-total markets were investigated but not originated, because no verified official scoring-average inputs for both teams were confirmed at the snapshot. Those fields are intentionally blank rather than estimated. Match-winner lines were originated only where the inputs in the row's basis are verified.</li></ol></div>"""
open(os.path.join(DOCS,"flagged.html"),"w").write(f"<!doctype html><html><head><meta charset='utf-8'><title>Flagged for Review — OLBG4</title><link rel='stylesheet' href='assets.css'></head><body>{nav()}<main><h1>Flagged for Review</h1><p>Every item below is published deliberately: a value could not be confirmed from an official source, so it was left blank. Nothing here blocks the site.</p>{extra}{table(flagged)}</main></body></html>")
meth="""<h1>Methodology, market investigation &amp; reverse-engineering notes</h1>
<div class='card'><h2>What OLBG is (reverse-engineered from OLBG.com, checked 21 Oct 2026)</h2><p>OLBG's betting-tips index states it covers 20+ sports with community tips, tipster competitions per sport, and selections ordered by number of tips. Its published sport list (source: <a href='https://www.olbg.com/betting-tips'>olbg.com/betting-tips</a>) is: Football, Horse Racing, Tennis, Golf, American Football, Baseball, Basketball, Boxing/UFC, Cricket, Cycling, Darts, Gaelic Football, Greyhound Racing, Handball, Hurling, Ice Hockey, Motor Racing, Rugby League, Rugby Union, Snooker, Volleyball and Specials. We do <strong>not</strong> copy OLBG's tips, odds or text; we originate our own lines below and use OLBG only to define the sport universe and as a cross-check that flagged three discrepancies (see Flagged page).</p>
<p><strong>Excluded by the brief:</strong> soccer (= OLBG Football), boxing, UFC/MMA (= OLBG Boxing/UFC), football/American football, hurling, horse racing, cycling, specials. <strong>Included (15):</strong> Tennis, Golf, Baseball, Basketball, Cricket, Darts, Gaelic Football, Greyhound Racing, Handball, Ice Hockey, Motor Racing, Rugby League, Rugby Union, Snooker, Volleyball.</p></div>
<div class='card'><h2>Originated-lines model (Model v1 — ours, not a bookmaker's)</h2><p><code>p_home = clamp(0.5 + 0.7 × (rating_home − rating_away) + home_edge, 0.08, 0.92)</code>, home_edge = 0.03 (0 at neutral venues). Decimal price = (1 ÷ p) × 0.96, rounded to 2dp; the 0.96 is our margin so prices are visibly our own. Ratings are built <em>only</em> from the verified facts printed in each row's “Verified basis” cell (official standings points %, official seedings, official last-round results, official win %). Where no verified rating exists, ratings are 0.50/0.50 (home prior only, Low confidence) or, for knockout/draw-dependent sports, the line is left blank and flagged. Confidence: High only where the model edge is strong <em>and</em> corroborated by the verified form in the basis; every High row carries a unique, non-templated prediction of at least 30 words naming the selection. Low/Medium rows carry their verified basis but no long-form prediction.</p></div>
<div class='card'><h2>Markets investigated per sport</h2><table><tr><th>Sport</th><th>Markets investigated</th><th>Originated?</th></tr>
<tr><td>Basketball / Ice Hockey / Rugby Union / Rugby League / Handball / Baseball / Gaelic Football / Volleyball</td><td>Match winner; handicap; match total</td><td>Match winner only. Handicap/total investigated but <strong>not originated</strong> — no verified official scoring averages for both sides at snapshot (blank, flagged).</td></tr>
<tr><td>Darts / Snooker</td><td>Win match; handicap (legs/frames); match total</td><td>Darts win-match originated from official PDC seedings. Snooker not originated where opponent/rankings unverified (blank, flagged).</td></tr>
<tr><td>Cricket</td><td>Match winner (limited-overs). Handicap/total do not apply in standard form</td><td>Not originated where rankings/form unverified (blank/low, flagged); NZ v India pick is home-team Low only.</td></tr>
<tr><td>Tennis</td><td>Match winner; set handicap; total games</td><td>Not originated — no verified head-to-head pairings at snapshot (flagged tournament rows).</td></tr>
<tr><td>Golf</td><td>Tournament winner (outright). No head-to-head match in stroke play</td><td>Not originated — player form unverified in session (flagged).</td></tr>
<tr><td>Motor Racing</td><td>Race winner</td><td>Not originated — qualifying not run, standings unverified in session (flagged).</td></tr>
<tr><td>Greyhound Racing</td><td>Race winner</td><td>Not originated — declared runners/traps unverified in session (flagged).</td></tr></table></div>
<div class='card'><h2>Verification rule applied to every row</h2><p>Every table row has a source link to an official governing-body/league/tour site (NBA.com, NHL.com, URC, Premiership Rugby, NRL, EHF, PDC, MLB, NZC/ICC, Galway/Cork GAA, Volleyball World, WST, ATP, DP World Tour, Formula1.com, GBGB). If a value could not be confirmed there, it is blank and the row is on the Flagged for Review page. Data files: <code>data/rows.csv</code> and <code>data/rows.json</code> in the repository. No OLBG odds, tips or wording are reproduced.</p></div>"""
open(os.path.join(DOCS,"methodology.html"),"w").write(f"<!doctype html><html><head><meta charset='utf-8'><title>Methodology — OLBG4</title><link rel='stylesheet' href='assets.css'></head><body>{nav()}<main>{meth}</main></body></html>")
from collections import Counter
c=Counter(r["sport"] for r in R)
high=[r for r in R if r["confidence"]=="High"]
cards="".join(f"<div class='card'><h3><a href='sports/{slug(s)}.html'>{e(s)}</a></h3><p>{c[s]} row(s) · {sum(1 for r in R if r['sport']==s and r['confidence']=='High')} high-confidence · {sum(1 for r in R if r['sport']==s and r['status']=='Flagged')} flagged</p></div>" for s in SPORTS)
open(os.path.join(DOCS,"index.html"),"w").write(f"<!doctype html><html><head><meta charset='utf-8'><title>OLBG4 — Originated Lines Dashboard</title><link rel='stylesheet' href='assets.css'></head><body>{nav()}<main><h1>Every included sport. Our own lines. Every row sourced.</h1><p><strong>{len(R)} rows</strong> for 21–25 Oct 2026 across <strong>{len(SPORTS)} included sports</strong> · {len(high)} high-confidence picks with full written predictions · {len(flagged)} flagged rows published openly. Excluded per brief: soccer, boxing, UFC/MMA, American football, hurling, horse racing, cycling, specials.</p>{cards}<div class='card'><h2>High-confidence picks</h2>{table(high)}</div></main></body></html>")
print("pages built", len(SPORTS))
